widget.solution:
class HitCounter:
    def __init__(self):
        self.times = [0] * 300
        self.counts = [0] * 300

    def hit(self, t):
        i = t % 300
        if self.times[i] != t:
            self.times[i], self.counts[i] = t, 0
        self.counts[i] += 1

    def count(self, t):
        return sum(c for s, c in zip(self.times, self.counts) if t - 300 < s <= t)

widget.postlude:
def run_hits(ops):
    h = HitCounter()
    out = []
    for op in ops:
        if op[0] == 0:
            h.hit(op[1])
        else:
            out.append(h.count(op[1]))
    return out
